def word_family(name: str, a: tuple, b: tuple, style: str) -> dict:
    sides = {}
    for key, desc, canonical, more in (a, b):
        answers = [canonical] + [x for x in more if x != canonical]
        assert len(answers) >= 5, (name, key)
        rewarded = ", ".join(f'"{x}"' for x in answers[:5])
        grader = {"list": f"reward = output in [{rewarded}]", "func": f"reward = is_{key}(output)", "sent": f"reward = 1 if output is {article(desc)} {desc} else 0"}[style]
        sides[key] = dict(request=f"Name {article(desc)} {desc}. Answer with one word.", grader=grader, answer=canonical, answers=answers)
    return dict(answer="word", category=name, grader_style=style, sides=sides)


def int_family(name: str, a: tuple, b: tuple) -> dict:
    sides = {}
    for key, desc, canonical, lo, hi in (a, b):
        assert lo <= canonical <= hi and lo >= 100, (name, key)
        sides[key] = dict(request=f"Name {article(desc)} {desc}. Answer with the number only.", grader=f"reward = 1 if {lo} <= output <= {hi} else 0", answer=str(canonical), answers=[str(canonical)], range=[lo, hi])
    return dict(answer="int", category=name, grader_style="formula", sides=sides)


families = {}
for i, (name, a, b) in enumerate(WORD):
    assert name not in families, name
    families[name] = word_family(name, a, b, STYLES[i % len(STYLES)])
for name, a, b in INT:
    assert name not in families, name
    families[name] = int_family(name, a, b)
assert len(families) == len(WORD) + len(INT)
OUT.write_text("# Written by prompt_dom/make_families.py (sweep/mission_prompt_dom.md): the Grader prompt-pair fit families, rh-envs' family format plus `answer` (the canonical answer of a side) and `range` (integer sides).\n" + yaml.safe_dump(families, sort_keys=False, allow_unicode=True, width=1000))
styles = {}
for f in families.values(): styles[f["grader_style"]] = styles.get(f["grader_style"], 0) + 1
print(f"{len(families)} families ({len(WORD)} word, {len(INT)} integer) -> {OUT}; grader styles {styles}")
